    if (useMlock) {
        Napi::Error::New(info.Env(), "Prism does not support useDirectIo with useMlock when useMmap is false")
            .ThrowAsJavaScriptException();
        return;
    }
    model_params.load_mode = LLAMA_LOAD_MODE_DIRECT_IO;
} else {
    model_params.load_mode = useMlock ? LLAMA_LOAD_MODE_MLOCK : LLAMA_LOAD_MODE_NONE;
}

