export async function getClonedLlamaCppRepoReleaseInfo() {
    const cloned = await isLlamaCppRepoCloned(false);
    const prismStampPath = path.join(path.dirname(llamaCppDirectory), "quenderin-prism-node-runtime.json");
    if (!cloned && (await fs.pathExists(llamaCppDirectory) ||
        !(await fs.pathExists(prismStampPath)) ||
        await isLockfileActive({ resourcePath: llamaCppDirectory })))
        return null;
    if (!(await fs.pathExists(llamaCppDirectoryInfoFilePath)))
        return null;
    try {
        const clonedLlamaCppRepoTagJson = await fs.readJson(llamaCppDirectoryInfoFilePath);
        if (!cloned) {
            // Packaged Quenderin retains verified build metadata, not a source checkout.
            const prism = await fs.readJson(prismStampPath);
            if (prism.version !== 1 ||
                prism.repository !== "https://github.com/PrismML-Eng/llama.cpp.git" ||
                prism.revision !== "e8fd209c975c80aa7fb36a8423571ff3b1b7e955" ||
                prism.nodeLlamaCppVersion !== "3.19.1" ||
                clonedLlamaCppRepoTagJson.llamaCppGithubRepo !== "PrismML-Eng/llama.cpp" ||
                clonedLlamaCppRepoTagJson.tag !== prism.revision)
                return null;
        }
        return clonedLlamaCppRepoTagJson;
    }
    catch (err) {
        console.error(getConsoleLogPrefix() + "Failed to read llama.cpp tag file", err);
        return null;
    }
}
